		MACH_MSGH_BITS(19, MACH_MSG_TYPE_MAKE_SEND_ONCE);
	/* msgh_size passed as argument */
	InP->Head.msgh_request_port = voucher;
	InP->Head.msgh_reply_port = mig_get_reply_port();
